345	     *                                     name of every offending field
346	     */
347	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
348	        List<String> missingFields = new ArrayList<>();
349	        if (isBlank(ownerFieldsDto.getFirstName())) {
350	            missingFields.add("firstName");
