389	    /**
390	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
391	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
392	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
393	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
394	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
395	     * The returned value is stored and returned unchanged.
396	     *
397	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
398	     * @param region   the owner's region derived from its city
399	     * @return the postcode to store, or {@code null} if none was supplied
400	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
401	     *                                     out of range for the city's region, yielding a 400 response
402	     */
403	    private String validatePostcode(String postcode, String region) {
404	        if (postcode == null) {
405	            return null;
406	        }
407	        if (!postcode.matches("[0-9]{4}")) {
408	            throw new InvalidOwnerFieldsException(List.of("postcode"));
409	        }
410	        int[] range = REGION_POSTCODES.get(region);
411	        if (range != null) {
412	            int value = Integer.parseInt(postcode);
413	            if (value < range[0] || value > range[1]) {
414	                throw new InvalidOwnerFieldsException(List.of("postcode"));
415	            }
416	        }
417	        return postcode;
418	    }
