420	    /**
421	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
422	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
423	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
424	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
425	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
426	     *
427	     * @param telephone the raw telephone value submitted by the client
428	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
429	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
430	     *                                     400 response
431	     */
432	    private String normalizeTelephone(String telephone) {
433	        String e164 = toE164(telephone);
434	        if (e164 == null) {
435	            throw new InvalidOwnerFieldsException(List.of("telephone"));
436	        }
437	        return e164;
438	    }
439	
440	    /**
441	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
442	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
443	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
444	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
445	     * and when the supplied country code is one with a known national-number length
446	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
447	     * number must have exactly that many digits.
448	     *
449	     * @param telephone the raw telephone value, possibly {@code null}
450	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
451	     */
452	    private String toE164(String telephone) {
453	        if (telephone == null) {
454	            return null;
455	        }
456	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
457	        boolean hasPlus = cleaned.startsWith("+");
458	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
459	        String nationalSignificant = hasPlus
460	            ? digits
461	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
462	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
463	            return null;
464	        }
465	        if (!hasValidNationalNumberLength(nationalSignificant)) {
466	            return null;
467	        }
468	        return "+" + nationalSignificant;
469	    }
470	
471	    /**
472	     * Checks the national-number length of an E.164 number (country code plus national significant
473	     * digits, no leading {@code '+'}) against the per-country requirement in
474	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
475	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
476	     * country code is not listed carries no per-country length requirement and is accepted.
477	     *
478	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
479	     *                            leading {@code '+'}
480	     * @return {@code true} if the national-number length is correct for the country code, or the
481	     *         country code has no listed requirement; {@code false} otherwise
482	     */
483	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
484	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
485	            .filter(nationalSignificant::startsWith)
486	            .max(Comparator.comparingInt(String::length))
487	            .orElse(null);
488	        if (countryCode == null) {
489	            return true;
490	        }
491	        int nationalLength = nationalSignificant.length() - countryCode.length();
492	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
493	    }
494	
495	    /**
496	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
497	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
498	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
499	     * returned value is that address lower-cased.
500	     *
501	     * @param email the raw email value submitted by the client, or {@code null} if omitted
502	     * @return the lower-cased email, or {@code null} if none was supplied
503	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
504	     *                                     or its domain is a disposable-mail domain, yielding a 400
505	     *                                     response
506	     */
507	    private String normalizeEmail(String email) {
508	        if (email == null) {
509	            return null;
510	        }
511	        if (!EMAIL_PATTERN.matcher(email).matches()) {
512	            throw new InvalidOwnerFieldsException(List.of("email"));
513	        }
514	        String normalized = email.toLowerCase(Locale.ROOT);
515	        String domain = normalized.substring(normalized.indexOf('@') + 1);
516	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
517	            throw new InvalidOwnerFieldsException(List.of("email"));
518	        }
519	        return normalized;
520	    }
