522	    /**
523	     * Counts the existing owners that, before this create, already share the given first name and
524	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
525	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
526	     * been saved yet, so it is never included in the count.
527	     *
528	     * @param firstName the first name of the owner being created
529	     * @param lastName  the last name of the owner being created
530	     * @return the number of existing owners sharing both names
531	     */
532	    private int countNamesakes(String firstName, String lastName) {
533	        String normalizedFirstName = normalizeForComparison(firstName);
534	        String normalizedLastName = normalizeForComparison(lastName);
535	        return (int) this.clinicService.findAllOwners().stream()
