541	    /**
542	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
543	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
544	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
545	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
546	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
547	     * same postcode region, telephone and last name always yield the same customer code.
548	     *
549	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
550	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
551	     * it unique, so distinct owners always receive distinct customer codes.
552	     *
553	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
554	     * @param telephone the owner's normalized (E.164) telephone
555	     * @param lastName  the owner's last name
556	     * @return the formatted, de-duplicated customer code
557	     */
558	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
559	        String region = regionForPostcode(postcode);
560	        String hash8 = hashHex(telephone + lastName, 8);
561	        String baseCode = region + "-" + hash8;
562	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
563	            .map(Owner::getCustomerCode)
564	            .filter(Objects::nonNull)
565	            .collect(Collectors.toSet());
566	        if (!existingCodes.contains(baseCode)) {
567	            return baseCode;
568	        }
569	        int n = 2;
570	        while (existingCodes.contains(baseCode + "-" + n)) {
571	            n++;
572	        }
573	        return baseCode + "-" + n;
574	    }
575	
576	    /**
577	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
578	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
579	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
580	     * {@code <REGION>} segment baked into the {@code customerCode}.
581	     *
582	     * @param postcode the owner's postcode, or {@code null}
583	     * @return the region code, or {@code 'UNKNOWN'}
584	     */
585	    private String regionForPostcode(String postcode) {
586	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
587	            return "UNKNOWN";
588	        }
589	        int value = Integer.parseInt(postcode);
590	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
591	            int[] range = entry.getValue();
592	            if (value >= range[0] && value <= range[1]) {
593	                return entry.getKey();
594	            }
595	        }
596	        return "UNKNOWN";
597	    }
598	
599	    /**
600	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
601	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
602	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
603	     * region.
604	     *
605	     * @param city the owner's city
606	     * @return the region code, or {@code 'UNKNOWN'}
607	     */
608	    private String regionForCity(String city) {
609	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
610	    }
611	
612	    /**
613	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
614	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
615	     * deterministic {@code householdId} (length 12).
616	     *
617	     * @param input  the value to hash
618	     * @param length the number of leading hex characters to return
619	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
620	     */
621	    private String hashHex(String input, int length) {
622	        try {
623	            byte[] digest = MessageDigest.getInstance("SHA-256")
624	                .digest(input.getBytes(StandardCharsets.UTF_8));
625	            StringBuilder hex = new StringBuilder(digest.length * 2);
626	            for (byte b : digest) {
627	                hex.append(String.format("%02x", b));
628	            }
629	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
630	        } catch (NoSuchAlgorithmException e) {
631	            throw new IllegalStateException("SHA-256 algorithm not available", e);
632	        }
633	    }
