635	    /**
636	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
637	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
638	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
639	     * has not been saved yet, so it is never included in the count.
640	     *
641	     * @param city the city of the owner being created
642	     * @return the number of existing owners in that city
643	     */
644	    private int countOwnersInCity(String city) {
645	        String normalizedCity = normalizeForComparison(city);
646	        return (int) this.clinicService.findAllOwners().stream()
647	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
648	            .count();
649	    }
