685	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
686	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
687	     *
688	     * @param registrationDate the business day to count owners for
689	     * @return the number of existing owners registered on that day
690	     */
691	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
692	        return this.clinicService.findAllOwners().stream()
693	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
694	            .count();
695	    }
696	
697	    /**
698	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
699	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
700	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
701	     * otherwise.
702	     *
703	     * @param ownerDto the owner response to flag
704	     */
705	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
706	        LocalDate today = toBusinessDay(LocalDate.now());
707	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
708	    }
709	
710	    /**
711	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
712	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
713	     * applies to the effective registration date whether it was supplied in the request or defaulted
714	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
715	     * feeds every value derived from it (such as the membership number's year segment and the daily
716	     * create-limit's per-day bucket).
717	     *
718	     * @param date the effective registration date, supplied or defaulted
719	     * @return the same date when it is a weekday, otherwise the next Monday
720	     */
721	    private LocalDate toBusinessDay(LocalDate date) {
722	        LocalDate adjusted = date;
723	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
724	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
725	            adjusted = adjusted.plusDays(1);
726	        }
727	        return adjusted;
728	    }
729	
730	    /**
731	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
732	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
733	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
734	     * separate telephone, email and household checks are all expressed through it. Because the
735	     * telephone is part of the key, two members of the same household (same {@code householdId})
736	     * with different telephones have different identity keys and are both allowed; only a whole-key
737	     * match is a duplicate. The owner being created already carries its normalized telephone,
738	     * email and (if any) household id, and existing owners store the same normalized forms, so the
739	     * keys are compared directly.
740	     *
741	     * @param owner the owner being created, with its telephone, email and household id already set
742	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
743	     *                                         yielding a 409 Conflict response
744	     */
745	    private void rejectDuplicateIdentity(Owner owner) {
746	        String identityKey = owner.getIdentityKey();
747	        boolean inUse = this.clinicService.findAllOwners().stream()
748	            .map(Owner::getIdentityKey)
749	            .anyMatch(identityKey::equals);
750	        if (inUse) {
751	            throw new DuplicateOwnerIdentityException(identityKey);
752	        }
753	    }
754	
755	    /**
756	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
757	     * that is not a hard duplicate (its identity key is unique, so it has already passed
758	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
759	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
760	     * while carrying a different telephone. When such a match exists the owner is created with
761	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
762	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
763	     * {@code false} and {@code possibleDuplicateOf} is left unset.
764	     *
765	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
766	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
767	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
768	     * survives for a created owner either.)
769	     *
770	     * @param owner           the owner being created, with its household id and telephone already set
771	     * @param sharesHousehold whether the owner declared itself a member of an existing household
772	     */
773	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
774	        owner.setPossibleDuplicate(false);
775	        if (sharesHousehold) {
776	            return;
777	        }
778	        String householdId = owner.getHouseholdId();
779	        if (householdId == null || householdId.isBlank()) {
780	            return;
781	        }
782	        String telephone = owner.getTelephone();
783	        Owner match = this.clinicService.findAllOwners().stream()
784	            .filter(existing -> householdId.equals(existing.getHouseholdId())
785	                && !Objects.equals(telephone, existing.getTelephone()))
786	            .min(Comparator.comparingInt(Owner::getId))
787	            .orElse(null);
788	        if (match != null) {
789	            owner.setPossibleDuplicate(true);
790	            owner.setPossibleDuplicateOf(match.getId());
791	        }
792	    }
793	
794	    /**
795	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
796	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
797	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
798	     * shares both automatically shares the same household id, so the household is keyed on
799	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
800	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
801	     * still land in the same household.
802	     *
803	     * @param lastName the owner's last name
804	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
805	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
806	     *         to no postcode-keyed household
807	     */
808	    private String computeHouseholdId(String lastName, String postcode) {
809	        if (postcode == null) {
810	            return null;
811	        }
812	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
813	    }
814	
815	    /**
816	     * Rejects creation of an owner that would join an existing household it has not declared membership
817	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
818	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
819	     * household. A second owner in that household is a household duplicate and is rejected with a
820	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
821	     * check is bypassed and the owner is created as a declared household member. An owner with no
822	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
823	     *
824	     * @param owner the owner being created, with its household id already computed
825	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
826	     *                                     household, yielding a 409 Conflict response
827	     */
828	    private void rejectHouseholdDuplicate(Owner owner) {
829	        String householdId = owner.getHouseholdId();
830	        if (householdId == null || householdId.isBlank()) {
831	            return;
832	        }
833	        boolean inUse = this.clinicService.findAllOwners().stream()
834	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
835	        if (inUse) {
836	            throw new DuplicateHouseholdException(householdId);
837	        }
838	    }
839	
840	    /**
841	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
842	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
843	     * the result is lower-cased.
844	     *
845	     * @param value the value to normalize, possibly {@code null}
846	     * @return the normalized value, or an empty string if {@code value} is {@code null}
847	     */
848	    private String normalizeForComparison(String value) {
849	        if (value == null) {
850	            return "";
851	        }
852	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
853	    }
854	
855	    /**
856	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
857	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
858	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
859	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
860	     * This normalized value is what gets stored and returned.
861	     *
862	     * @param address the raw address value submitted by the client, possibly {@code null}
863	     * @return the normalized address, or an empty string if {@code address} is {@code null}
864	     */
865	    private String normalizeAddress(String address) {
866	        if (address == null) {
867	            return "";
868	        }
869	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
870	        if (collapsed.isEmpty()) {
871	            return collapsed;
872	        }
873	        String[] tokens = collapsed.split(" ");
874	        StringBuilder normalized = new StringBuilder(collapsed.length());
875	        for (int i = 0; i < tokens.length; i++) {
876	            if (i > 0) {
877	                normalized.append(' ');
878	            }
879	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
880	        }
881	        return normalized.toString();
882	    }
883	
884	    /**
885	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
886	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
887	     * preferred when present, but either satisfies the address requirement, keeping the create
888	     * contract backward-compatible with earlier flat-address-only owners.
889	     *
890	     * @param ownerFieldsDto the submitted owner fields
891	     * @return {@code true} if an address is supplied in either form
892	     */
893	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
894	        return !isBlank(ownerFieldsDto.getAddressLine1())
895	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
896	    }
897	
898	    /**
899	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
900	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
901	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
902	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
903	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
904	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
905	     * working while letting everything that reads the address use the composed, normalized value.
906	     *
907	     * @param owner          the owner being created
908	     * @param ownerFieldsDto the submitted owner fields
909	     */
910	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
911	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
912	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
913	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
914	                ? null
915	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
916	            owner.setAddressLine1(line1);
917	            owner.setAddressLine2(line2);
918	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
919	        } else {
920	            owner.setAddressLine1(null);
921	            owner.setAddressLine2(null);
922	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
923	        }
924	    }
925	}
